const app=document.querySelector('#app');
const startOverButton=document.querySelector('#startOver');
const homeLink=document.querySelector('#homeLink');
const KEY='missing-hours-progress-v5';
let state={screen:'intro',name:'',username:'',tries:0,code:'',word:[],sudoku:{}};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&typeof saved==='object')state={...state,...saved}}catch{}
if(!['intro','sudoku','scrabble','login','folder','locked','hunt','book','studio','closed'].includes(state.screen))state.screen='intro';
if(!state.sudoku||typeof state.sudoku!=='object')state.sudoku={};
if(!Array.isArray(state.word))state.word=[];
if(!Array.isArray(state.rackOrder))state.rackOrder=[];
state.word=state.word.map(v=>Number.isInteger(v)?v:undefined);
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}};
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function go(screen){state.screen=screen;save();render();window.scrollTo({top:0,behavior:'smooth'})}
function resetHunt(){localStorage.removeItem(KEY);state={screen:'intro',name:'',username:'',tries:0,code:'',word:[],sudoku:{}};render();window.scrollTo({top:0,behavior:'smooth'})}
homeLink.onclick=e=>{e.preventDefault();resetHunt()};
startOverButton.onclick=()=>{if(!window.confirm('Start from the beginning? Your saved place in the hunt will be cleared.'))return;resetHunt()};
const FINAL_FILE_DIGEST='fcd22f0899f3ee64f5eeaecf34b8e57073a62decb51957147ce626d4d3059d12';
const BOOK_MAGIC_DIGEST='3c2ee28babb6d5fa82d08975497facd92dee9efedc07acba0a3b69e6ed4bea4a';
async function checkFinalPassword(value){try{const bytes=new TextEncoder().encode(value.trim().toLowerCase().replace(/\s+/g,''));const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')===FINAL_FILE_DIGEST}catch{return false}}
async function checkBookMagic(value){const bytes=new TextEncoder().encode(value.trim().toLowerCase().replace(/\s+/g,''));const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('')===BOOK_MAGIC_DIGEST}
const FISH_HINT_DATA='data:image/jpeg;base64,';
const YUJO_LOGO_DATA='data:image/png;base64,';
function revealUsernameHint(){const host=document.querySelector('#loginHint');host.innerHTML=`<div class="hint-scene"><img class="image-hint" src="${FISH_HINT_DATA}" alt="Dual Fishes picture hint: a painted portrait with red fish covering the eyes">${catDoodles()}</div><div class="hint-label">DISCORD USERNAME</div>`}
const CAT_DOODLE='<svg viewBox="0 0 76 68" aria-hidden="true"><path d="M15 27 12 8l17 11q9-5 18 0L64 8l-3 21q4 7 1 16-5 15-24 15T14 45q-4-10 1-18Z"/><path d="M25 35h1m24 0h1m-14 7 4 3-4 3m-7 2q7 5 14 0M17 41 5 38m12 9L4 49m55-8 12-3m-12 9 13 2"/><path d="M20 24q7-7 14-1m8 0q7-6 14 1"/></svg>';
function catDoodles(){const one=()=>{const x=Math.round(8+Math.random()*66),y=Math.round(-5+Math.random()*100),turn=Math.round(-14+Math.random()*28);return '<span class="cat-doodle" style="left:'+x+'%;top:'+y+'px;--turn:'+turn+'deg">'+CAT_DOODLE+'</span>'};return one()+one()}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function frame(step,title,body,actions=''){return `<div class="step-head"><div><div class="eyebrow">${step}</div><h1 class="section-title">${title}</h1></div><div class="step-no">CRAZYSTUFF<br>BIRTHDAY TREASURE HUNT</div></div><div class="progress"><span style="width:${({'01 · THE GRID':'15%','02 · THE LETTERS':'30%','03 · ACCESS':'45%','04 · THE FILE':'58%','05 · THE NEXT CLUE':'70%','06 · THE LAST CLUE':'88%','07 · CASE CLOSED':'100%'}[step]||'8%')}"></span></div>${body}${actions}`}
function render(){document.querySelector('#statusText').textContent=state.screen==='closed'?'CASE CLOSED':'CASE OPEN';startOverButton.hidden=state.screen==='intro';
if(state.screen==='intro'){app.innerHTML=`<section class="hero"><div><div class="eyebrow">A BIRTHDAY ADVENTURE · LITTLE MYSTERIES</div><h1 class="title">Crazystuff<br><em>Birthday Treasure Hunt</em></h1><p class="lede">A <span class="highlight-coral">curious</span> trail, a few <span class="highlight-rose">small puzzles</span>, and a <span class="highlight-olive">message</span> waiting at the end. Follow each clue and see <span class="highlight-lilac">what</span> has been tucked away just for you.</p><p class="muted">The trail begins with a puzzle and winds toward a little mystery made just for you.</p><div class="actions"><button class="button" id="begin">Begin the hunt <span aria-hidden="true">↗</span></button></div><p class="smallprint">BEST EXPERIENCED ON YOUR PHONE · TAKE YOUR TIME</p></div><div class="hero-art" aria-hidden="true">${catDoodles()}</div></section>`;document.querySelector('#begin').onclick=()=>go('sudoku')}
if(state.screen==='sudoku'){const puzzle=['103000','050120','004560','000004','040610','610305'];const solved=['123456','456123','234561','561234','345612','612345'];if(state.gridSize!==6){state.sudoku={};state.gridSize=6;save()}if(!state.sudoku||typeof state.sudoku!=='object')state.sudoku={};for(let i=0;i<36;i++){const r=Math.floor(i/6),c=i%6;if(state.sudoku[i]===undefined)state.sudoku[i]=puzzle[r][c]}const cells=Array.from({length:36},(_,i)=>{const r=Math.floor(i/6),c=i%6,v=state.sudoku[i],given=puzzle[r][c]!=='0';return `<input class="cell ${given?'given':''}" data-i="${i}" aria-label="Row ${r+1}, column ${c+1}" inputmode="numeric" maxlength="1" ${given?'readonly':''} value="${v==='0'?'':safe(v)}">`}).join('');app.innerHTML=frame('01 · THE GRID','A pattern in the margins',`<p class="muted">A 6 × 6 Sudoku has been left unfinished. Fill the empty squares with the numbers 1–6. Every row, column, and 2 × 3 box must use each number once.</p><div class="sudoku six">${cells}</div><p class="smallprint" style="text-align:center">6 × 6 · CHALLENGE · NUMBERS 1–6</p>`,`<div class="actions" style="justify-content:center"><button class="button" id="check" type="button">Check the evidence</button><button class="button secondary" id="reset" type="button">Reset grid</button></div>`);const syncGrid=()=>{document.querySelectorAll('.cell').forEach(el=>{state.sudoku[el.dataset.i]=el.value||'0'})};document.querySelectorAll('.cell:not([readonly])').forEach(el=>{const update=()=>{el.value=el.value.replace(/[^1-6]/g,'').slice(0,1);state.sudoku[el.dataset.i]=el.value||'0';save()};el.addEventListener('input',update);el.addEventListener('change',update)});document.querySelector('#check').onclick=()=>{syncGrid();const entered=Array.from({length:36},(_,i)=>state.sudoku[i]);const ok=solved.every((row,r)=>row.split('').every((n,c)=>entered[r*6+c]===n));if(ok){state.screen='scrabble';save();render();window.scrollTo({top:0,behavior:'smooth'})}else{save();toast('Not quite. Check each row, column, and 2 × 3 box.')}};document.querySelector('#reset').onclick=()=>{state.sudoku={};for(let i=0;i<36;i++){const r=Math.floor(i/6),c=i%6;state.sudoku[i]=puzzle[r][c]}save();render()}}
if(state.screen==='scrabble'){const letters=[['D',2],['U',1],['A',1],['L',1],['F',4],['I',1],['S',1],['H',4],['E',1],['S',1]];if(!Array.isArray(state.word))state.word=[];if(state.rackOrder.length!==letters.length||new Set(state.rackOrder).size!==letters.length||state.rackOrder.some(i=>!Number.isInteger(i)||i<0||i>=letters.length)){state.rackOrder=letters.map((_,i)=>i);for(let i=state.rackOrder.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[state.rackOrder[i],state.rackOrder[j]]=[state.rackOrder[j],state.rackOrder[i]]}save()}const tiles=state.rackOrder.filter(i=>!state.word.includes(i)).map(i=>`<button class="tile" data-tile="${i}" aria-label="Letter ${letters[i][0]}"><span>${letters[i][0]}</span><small>${letters[i][1]}</small></button>`).join('');const premium=(r,c)=>((r===0||r===10)&&[0,5,10].includes(c))||((c===0||c===10)&&r===5)?['tw','TW']:((r===1||r===9)&&[1,5,9].includes(c))||((c===1||c===9)&&r===5)?['dw','DW']:((r===2||r===8)&&[2,8].includes(c))||((c===2||c===8)&&r===5)?['tl','TL']:((r===0||r===10)&&[3,7].includes(c))||((r===3||r===7)&&[0,10].includes(c))?['dl','DL']:null;const board=Array.from({length:121},(_,i)=>{const r=Math.floor(i/11),c=i%11;if(r===5)return `<button class="slot ${c===4?'space':''}" data-slot="${c}" aria-label="${c===4?'space':'Letter slot '+(c+1)}">${Number.isInteger(state.word[c])?letters[state.word[c]][0]:''}</button>`;const p=premium(r,c);return `<div class="board-square ${p?p[0]:''}">${p?p[1]:''}</div>`}).join('');app.innerHTML=frame('02 · THE LETTERS','Put the story back together',`<p class="eyebrow">LIVES IN WATER</p><p class="muted">Arrange the ten tiles to make the phrase. Tap a tile to place it; tap a placed tile to lift it back onto the rack.</p><div class="scrabble-board">${board}</div><div class="tile-rack">${tiles}</div><p class="smallprint" style="text-align:center">10 TILES · EVERY LETTER HAS A PLACE</p>`,`<div class="actions"><button class="button secondary" id="shuffle">⤨ Shuffle rack</button><button class="button secondary" id="undo">↶ Undo</button><button class="button secondary" id="wordreset">Clear</button><button class="button" id="wordcheck">Submit</button></div>`);document.querySelectorAll('.tile').forEach(b=>b.onclick=()=>{const next=Array.from({length:11},(_,i)=>i).find(i=>i!==4&&!Number.isInteger(state.word[i]));if(next===undefined){toast('All the letter spaces are filled.');return}state.word[next]=Number(b.dataset.tile);save();render()});document.querySelectorAll('.slot').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.slot);if(Number.isInteger(state.word[i])){state.word[i]=undefined;save();render()}});document.querySelector('#shuffle').onclick=()=>{for(let i=state.rackOrder.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[state.rackOrder[i],state.rackOrder[j]]=[state.rackOrder[j],state.rackOrder[i]]}save();render()};document.querySelector('#undo').onclick=()=>{for(let i=10;i>=0;i--){if(i!==4&&Number.isInteger(state.word[i])){state.word[i]=undefined;save();render();return}}toast('There is no tile to undo.')};document.querySelector('#wordreset').onclick=()=>{state.word=[];save();render()};document.querySelector('#wordcheck').onclick=()=>{let result=Array.from({length:11},(_,i)=>Number.isInteger(state.word[i])?letters[state.word[i]][0]:' ').join('').trim().replace(/\s+/g,' ').toLowerCase();if(result==='dual fishes')go('login');else toast('The letters have not quite found their place.')}}
if(state.screen==='login'){app.innerHTML=frame('03 · ACCESS','A name for the case',`<p class="muted">Every investigator leaves a name in the ledger. Choose one, then enter the phrase the letters revealed.</p><form class="form" id="loginForm"><label class="field-label" for="username">Investigator username</label><input class="input" id="username" autocomplete="nickname" placeholder="Choose a name" required value="${safe(state.username)}"><label class="field-label" for="password">Case password</label><input class="input" id="password" type="password" autocomplete="off" placeholder="The two-word phrase" required><button class="button" type="submit">Enter the archive ↗</button><div id="loginHint"></div></form><p class="smallprint">YOUR NAME IS KEPT ONLY IN THIS BROWSER.</p>`);document.querySelector('#loginForm').onsubmit=e=>{e.preventDefault();const user=document.querySelector('#username').value.trim(),pw=document.querySelector('#password').value.toLowerCase().replace(/\s+/g,'');state.username=user;if(pw==='dualfishes'){state.tries=0;save();go('folder')}else{state.tries++;save();toast('That phrase does not fit yet. Try again, investigator.');if(state.tries>=3)revealUsernameHint();}}}
if(state.screen==='folder'){app.innerHTML=frame('04 · THE ARCHIVE','One file remains',`<p class="muted">The archive is almost empty. One folder has been left on the desk.</p><button class="folder" id="openFolder"><span class="folder-icon">📁</span><span><strong>Birthday Gift</strong><small>1 LOCKED FILE · MODIFIED TODAY</small></span><span style="margin-left:auto;color:#a5a596">↗</span></button>`);document.querySelector('#openFolder').onclick=()=>go('locked')}
if(state.screen==='locked'){app.innerHTML=frame('04 · THE ARCHIVE','File locked',`<div class="card" style="max-width:500px"><div class="eyebrow">BIRTHDAY GIFT / FINAL-PAGE.TXT</div><h2 class="section-title">A password is needed.</h2><p class="muted">The file is sealed. Its password is waiting somewhere in the hunt. Keep the file name in mind.</p><form class="form" id="fileForm"><label class="field-label" for="filepw">File password</label><input class="input" id="filepw" autocomplete="off" placeholder="Enter password"><button class="button" type="submit">Unlock file</button></form></div><div class="modal" id="wrongModal" hidden><div class="modal-box"><div class="eyebrow">ACCESS DENIED</div><h3>Wrong password.</h3><p class="muted">File locked. Treasure hunt to continue.</p><button class="button" id="continueHunt">Continue the hunt</button></div></div>`);document.querySelector('#fileForm').onsubmit=async e=>{e.preventDefault();if(await checkFinalPassword(document.querySelector('#filepw').value)){go('closed')}else document.querySelector('#wrongModal').hidden=false};document.querySelector('#continueHunt').onclick=()=>go('hunt')}
if(state.screen==='hunt'){app.innerHTML=frame('05 · THE NEXT CLUE','Mystery gift coordinates',`<p class="lede">A new place. A missing book. And someone who knows more than they first let on.</p><p class="muted">Copy the coordinates to find the Muyenga stop. Once you arrive, ask around for the person holding a clue to the missing story. The right questions will lead you to the hidden book.</p><div class="coordinate-card"><div class="field-label">COORDINATES · MUYENGA</div><div class="copy-row"><input class="input coordinate-input" id="coordinates" value="0.2999331539338049, 32.606956511735504" readonly aria-label="Coordinates for the next stop"><button class="button secondary" id="copyCoordinates" type="button">Copy coordinates</button></div></div><div class="note-card"><p>When you find the keeper, ask with a little Shakespearean charm:</p><p>“Good keeper, hast thou some love to give?”</p><p>Listen closely. The word they offer will open the next clue.</p></div><form class="form" id="meetForm"><label class="field-label" for="meetAnswer">The keeper’s answer</label><input class="input" id="meetAnswer" autocomplete="off" placeholder="Enter the word they give you" required><button class="button" type="submit">I found the clue</button></form>`);document.querySelector('#copyCoordinates').onclick=async()=>{const input=document.querySelector('#coordinates');try{await navigator.clipboard.writeText(input.value);toast('Coordinates copied. The next stop is waiting in Muyenga.')}catch{input.focus();input.select();toast('Coordinates selected. Copy them to your map.')}};document.querySelector('#meetForm').onsubmit=e=>{e.preventDefault();if(document.querySelector('#meetAnswer').value.trim().toLowerCase()==='love')go('book');else toast('That is not the word the keeper offered. Ask once more.')}}
if(state.screen==='book'){app.innerHTML=frame('05 · THE NEXT CLUE','A little secret',`<p class="eyebrow">CLUE FOUND</p><h2 class="section-title">A little secret</h2><p class="lede">Some messages are meant for one person, tucked away until just the right moment.</p><div class="note-card">“For every laugh we have shared, every place we have wandered, and every little story still waiting for us. Keep this close, and let it lead you onward.”</div><p class="muted">A small note is hidden somewhere among the book’s pages. Read it carefully: its riddle points to the next place, and the secret phrase inside opens the next chapter.</p><div class="magic-hint">${catDoodles()}</div><form class="form" id="magicForm"><label class="field-label" for="magicWord">Secret phrase</label><input class="input" id="magicWord" autocomplete="off" placeholder="Words from the hidden note" required><button class="button" type="submit">Open the next chapter ↗</button></form>`);document.querySelector('#magicForm').onsubmit=async e=>{e.preventDefault();if(await checkBookMagic(document.querySelector('#magicWord').value))go('studio');else toast('That phrase does not fit yet.')};}
if(state.screen==='studio'){app.innerHTML=frame('06 · THE LAST CLUE','A new chapter',`<p class="lede">The book sent you somewhere new—but the next message is not waiting in plain sight.</p><p class="muted">Go to the studio and search slowly. One small clue has been hidden among the details of the room. Look carefully; the note you find will lead to the final page.</p><div class="trail"><div class="trail-item"><div class="trail-num">01</div><div><h3>Take in the room</h3><p>Notice what feels ordinary, and what feels just slightly out of place.</p></div></div><div class="trail-item"><div class="trail-num">02</div><div><h3>Read between the lines</h3><p>The hidden message may be smaller than the things around it.</p></div></div><div class="trail-item"><div class="trail-num">03</div><div><h3>Follow what you find</h3><p>There is one last note waiting to be discovered.</p></div></div></div><div class="note-card">“For every place you have yet to go, every page you have yet to turn, and all the little moments still ahead.”</div>`,`<div class="actions"><button class="button" id="foundClue">I found the clue</button></div><p class="smallprint">THE NOTE WITH YOUR LAST CLUE OPENS THE FINAL PAGE.</p>`);document.querySelector('#foundClue').onclick=()=>go('locked')}
if(state.screen==='closed'){app.innerHTML=frame('07 · CASE CLOSED','Happy Birthday, Lynnet!',`<p class="lede">Mon Cœur, you found the last page.</p><div class="note-card">“I wanted to give you something for the stories you’ll read, the places you’ll go, and all the time we still get to share. I’m so glad our paths crossed. Happy birthday, Lynnet. May this next chapter be your favorite yet. With all my love, Mon Cœur.”</div><p class="signoff">Love, Spooderman ❤️</p><div class="final-cats">${catDoodles()}</div><p class="muted">The case is closed. The story, of course, is still being written.</p><div class="eyebrow success">♡ CASE CLOSED · ARTIFACTS RECOVERED ♡</div>`);}
}
render();



